//! The hooks library of arvo's bench tree.
//!
//! The driver `mock bench run` generates from `bench.toml` compiles this file
//! in by path and calls `hooks()`. It contributes one thing: the routine each
//! bench measures where the input is not plain bytes. `fnv1a-vs-xxhash3` is
//! byte shaped and runs on the generated byte dispatch, whose points
//! `[dispatch]` in `bench.toml` declares; every other bench is keyed here.
//!
//! The routine types come from the support crates under `support/`, which the
//! generated driver takes as path dependencies. Which arms a row measures is
//! resolved from `bench.toml`, never from this table, so one routine per
//! (bench, point) serves every arm the row lists.
//!
//! `structural-decomposition` and `spectral-bisection` have no routine here. Their
//! routines lived in arms that depend on the `arvo` crate the canon work deleted,
//! so those arms do not build, and neither do `fnv1a` and `xxhash3` for the same
//! reason; a run naming any of them stops at the arm build, before this table is
//! asked.

use bench_bitpack_carrier_shared::CarrierColumn;
use bench_bitpack_contend_shared::Contend;
use bench_bitpack_footprint_shared::FootprintColumn;
use bench_bitpack_plan_shared::{MacColumn, PlanColumn};
use bench_bitpack_shared::Column;
use bench_bitpack_wide_shared::Wide;
use bench_bitpack_write_contend_shared::WriteContend;
use bench_quantiser_fadd_shared::AddSweep;
use bench_quantiser_radix_shared::RadixAdd;
use bench_satfold_shared::Case as SatFoldCase;
use bench_warm_clamp_shared::Case as ClampCase;
use bench_warm_container_shared::Case;
use bench_wide_rung_shared::Case as WideCase;
use mockspace_bench_harness::driver::Hooks;
use mockspace_bench_harness::routine_table;

/// The hooks the generated driver runs.
pub fn hooks() -> Hooks {
    Hooks {
        routine_for: Some(routine_table!(
            // A subnormal-fraction percentage per point; both arms share it.
            "quantiser-vs-fadd-subnormal-sweep" => AddSweep [0, 10, 25, 50, 75, 100],
            // An exponent spread per point, radix two against radix ten.
            "decimal-quantiser-radix-sweep" => RadixAdd [0, 2, 8, 20],
            // The two `Layout::Bitpacked` readings per column size.
            "bitpack-sequential-sum" => Column [256, 4096, 16384],
            "bitpack-random-sum" => Column [256, 4096, 16384],
            // One buffer read three ways, at sizes bracketing the L1 data cache.
            "bitpack-decoder-shape" => PlanColumn [16384, 65536, 98304, 262144],
            // The same decoders feeding a heavier per-element kernel.
            "bitpack-kernel-amortisation" => MacColumn [16384, 65536, 98304, 262144],
            // Container fork (panel file 141), one `Case<KEY>` per row.
            "warm-container-width-l1" => Case [80003, 130003, 160003, 320003, 600003, 640003],
            "warm-container-width-l2" => Case [81003, 131003, 161003, 321003, 601003, 641003],
            "warm-container-density-w13" => Case [130001, 130002, 130004, 130008, 130016],
            "warm-container-density-w64" => Case [640001, 640002, 640004, 640008, 640016],
            "precise-container-width-l1" => Case [80103, 130103, 160103, 320103, 600103, 640103],
            "warm-elementwise-width-l1" => Case [80204, 130204, 160204, 320204, 600204, 640204],
            "precise-elementwise-width-l1" => Case [80304, 130304, 160304, 320304, 600304, 640304],
            "warm-affine-collapse-l1" => Case [80403, 130403, 160403, 320403, 600403, 640403],
            "precise-widening-theorem-l1" => Case [80501, 130501, 160501, 320501, 600501, 640501],
            "warm-affine-density-w13" => Case [130401, 130402, 130404, 130408, 130416],
            // Clamping semantics (panel file 142), one `ClampCase<KEY>` per row.
            "warm-clamp-arity-w8" => ClampCase [80010, 80020, 80030, 80040],
            "warm-clamp-arity-w13" => ClampCase [130010, 130020, 130030, 130040, 130060, 130080],
            "warm-clamp-arity-w16" => ClampCase [160010, 160020, 160030, 160040, 160060, 160080],
            "warm-clamp-arity-w32" => ClampCase [320010, 320020, 320030, 320040, 320060, 320080],
            "warm-clamp-arity-w60" => ClampCase [600010, 600020, 600030, 600040, 600060, 600080],
            "warm-clamp-arity-w64" => ClampCase [640010, 640020, 640030, 640040, 640060, 640080],
            "warm-clamp-chain-l1" => ClampCase [80001, 130001, 160001, 320001, 600001, 640001],
            "warm-clamp-arity-l2" => ClampCase [81040, 131040, 161040, 321040, 601040, 641040],
            // Saturating-fold reassociation (panel file 92). KEY is
            // (LI+1)*1000 + NC*100 + AL*10 + OP; `bench-satfold-shared` has it.
            "satfold-length-l1" => SatFoldCase [
                1000, 2000, 3000, 4000, 5000, 6000, 7000, 8000, 9000, 10000, 11000, 12000
            ],
            "satfold-length-l1-wrap" => SatFoldCase [1001, 3001, 7001, 10001, 12001],
            "satfold-align-l1" => SatFoldCase [3010, 7010, 10010, 12010],
            "satfold-length-dram" => SatFoldCase [3100, 7100],
            "satfold-length-dram-long" => SatFoldCase [12100],
            "satfold-length-dram-wrap" => SatFoldCase [3101, 7101, 12101],
            "satfold-const-gate" => SatFoldCase [7000, 10000, 12000],
            // Footprint: dense and packed share one `FootprintColumn<N>`.
            "bitpack-footprint-dense" => FootprintColumn [
                16384, 65536, 1048576, 4194304, 7000000, 33554432
            ],
            "bitpack-footprint-packed" => FootprintColumn [
                16384, 65536, 1048576, 4194304, 7000000, 33554432
            ],
            "bitpack-footprint-headtohead" => FootprintColumn [
                16384, 65536, 1048576, 4194304, 7000000
            ],
            // The wide rung. KEY is W*1000 + NC*100 + D; `bench-wide-rung-shared`.
            "wide-rung-width-l1" => WideCase [129003, 160003, 192003, 200003, 232003, 256003],
            "wide-rung-width-l2" => WideCase [129103, 160103, 192103, 200103, 232103, 256103],
            "wide-rung-density-w200" => WideCase [200001, 200002, 200004, 200008],
            "wide-rung-walk-l2" => WideCase [129100, 160100, 192100, 200100, 232100, 256100],
            "wide-rung-walk-l1" => WideCase [129000, 160000, 192000, 200000, 232000, 256000],
            // Carrier width (panel file 26), five arms per row.
            "bitpack-carrier-width" => CarrierColumn [
                16384, 131072, 1048576, 2097152, 4194304, 8388608
            ],
            // Contention (panel file 27). KEY is N*10 + T, the column size and
            // the thread count travelling together as one const parameter.
            "bitpack-contention" => Contend [
                163841, 163842, 163844, 163848, 10485761, 10485762, 10485764, 10485768,
                41943041, 41943042, 41943044, 41943048, 83886081, 83886082, 83886084, 83886088
            ],
            "bitpack-contend-decode" => Contend [
                163841, 163844, 41943041, 41943044, 83886081, 83886084
            ],
            "bitpack-contend-best" => Contend [41943041, 41943044, 83886081, 83886084],
            // Write contention (panel file 78). "safe" sizes land every
            // internal boundary on the packed period and "race" sizes do not,
            // which `bench-bitpack-write-contend-shared`'s own tests pin.
            "bitpack-write-contend-safe" => WriteContend [
                655361, 655362, 655364, 20971521, 20971522, 20971524
            ],
            "bitpack-write-contend-race" => WriteContend [
                655341, 655342, 655344, 20971501, 20971502, 20971504
            ],
            // The u16 question at a column several times past L2 (panel file 27).
            "bitpack-wide" => Wide [
                83886081, 83886084, 167772161, 167772164, 335544321, 335544324
            ],
        )),
        ..Hooks::default()
    }
}
